parameters.bodyParametersJson:
={{ JSON.stringify({
  title: $json.title,
  contentFormat: 'html',
  content: $json.content || $json.contentSnippet,
  tags: ($json.categories || []).slice(0,5),
  publishStatus: 'draft',
  canonicalUrl: $json.link
}) }}

={{ JSON.stringify({
  author: 'urn:li:person:YOUR_LINKEDIN_USER_ID',
  lifecycleState: 'PUBLISHED',
  specificContent: {
    'com.linkedin.ugc.ShareContent': {
      shareCommentary: { text: `${$json.title}\n\n${$json.contentSnippet || ''}\n\nRead the full post: ${$json.link}` },
      shareMediaCategory: 'ARTICLE',
      media: [{ status: 'READY', originalUrl: $json.link }]
    }
  },
  visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' }
}) }}
